145	// 分钟数 -> YYYY-MM-DDTHH:mm；超出四位年份范围返回 null（绝不依赖机器时区）
146	function formatDateTime(min: number): string | null {
147	  const day = Math.floor(min / 1440);
148	  const rem = min - day * 1440;
149	  const {y, m, d} = civilFromDays(day);
150	  if (y < MIN_YEAR || y > MAX_YEAR) return null;
151	  return `${String(y).padStart(4, '0')}-${pad2(m)}-${pad2(d)}T${pad2(Math.floor(rem / 60))}:${pad2(rem % 60)}`;
152	}
