154	function parseDateTime(value: string, label: string): number {
155	  if (typeof value !== 'string' || value === '') {
156	    throw new BizError(`${label}缺失，应为 YYYY-MM-DDTHH:mm`);
157	  }
158	  const m = DATE_TIME_RE.exec(value);
159	  if (!m) {
160	    throw new BizError(`${label}格式非法: “${value}”，应为 YYYY-MM-DDTHH:mm`);
161	  }
162	  const year = Number(m[1]);
163	  const month = Number(m[2]);
164	  const day = Number(m[3]);
165	  const hour = Number(m[4]);
166	  const minute = Number(m[5]);
167	  if (year < MIN_YEAR || year > MAX_YEAR || month < 1 || month > 12 ||
168	      day < 1 || day > daysInMonth(year, month) ||
169	      hour > 23 || minute > 59) {
170	    throw new BizError(`${label}不是真实有效的时间: “${value}”`);
171	  }
172	  return daysFromCivil(year, month, day) * 1440 + hour * 60 + minute;
173	}
