175	function parseDate(value: string, label = '查询日期'): number {
176	  if (typeof value !== 'string' || value === '') {
177	    throw new BizError(`${label}缺失，应为 YYYY-MM-DD`);
178	  }
179	  const m = DATE_RE.exec(value);
180	  if (!m) {
181	    throw new BizError(`${label}格式非法: “${value}”，应为 YYYY-MM-DD`);
182	  }
183	  const year = Number(m[1]);
184	  const month = Number(m[2]);
185	  const day = Number(m[3]);
186	  if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
187	    throw new BizError(`${label}不是真实有效的日期: “${value}”`);
188	  }
189	  return daysFromCivil(year, month, day) * 1440;
190	}
