193	function parseOpenInterval(value: string): {start: string; end: string; startMin: number; endMin: number} {
194	  const parts = String(value ?? '').split('/');
195	  if (parts.length !== 2 || parts[0] === '' || parts[1] === '') {
196	    throw new BizError(`开放区间格式非法: “${value}”，应为 开始/结束（YYYY-MM-DDTHH:mm/YYYY-MM-DDTHH:mm）`);
197	  }
198	  const start = parts[0];
199	  const end = parts[1];
200	  const startMin = parseDateTime(start, '开放区间开始时间');
201	  const endMin = parseDateTime(end, '开放区间结束时间');
202	  if (endMin <= startMin) {
203	    throw new BizError(`开放区间结束时间必须晚于开始时间: “${value}”`);
204	  }
205	  return {start, end, startMin, endMin};
