208	// 重叠或相接（start <= 上一段 end）的区间合并为连续开放
209	function mergeIntervals(intervals: Array<[number, number]>): Array<[number, number]> {
210	  const sorted = [...intervals].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
211	  const merged: Array<[number, number]> = [];
212	  for (const [s, e] of sorted) {
213	    const last = merged[merged.length - 1];
214	    if (last && s <= last[1]) {
215	      if (e > last[1]) last[1] = e;
216	    } else {
217	      merged.push([s, e]);
218	    }
219	  }
220	  return merged;
221	}
