228	// 将一组已合并区间裁剪到窗口 [wStart, wEnd) 内（左闭右开），丢弃不相交段
229	function clipSegments(
230	  segments: Array<[number, number]>,
231	  wStart: number,
232	  wEnd: number,
233	): Array<[number, number]> {
234	  const out: Array<[number, number]> = [];
235	  for (const [s, e] of segments) {
236	    const a = Math.max(s, wStart);
237	    const b = Math.min(e, wEnd);
238	    if (a < b) out.push([a, b]);
239	  }
240	  return out;
241	}
