243	// 两组已合并区间的交集（左闭右开）；切点相接（b===a）长度为 0，自然不产生段
244	function intersectSegments(
245	  a: Array<[number, number]>,
246	  b: Array<[number, number]>,
247	): Array<[number, number]> {
248	  const out: Array<[number, number]> = [];
249	  let i = 0;
250	  let j = 0;
251	  while (i < a.length && j < b.length) {
252	    const lo = Math.max(a[i][0], b[j][0]);
253	    const hi = Math.min(a[i][1], b[j][1]);
254	    if (lo < hi) out.push([lo, hi]);
255	    if (a[i][1] < b[j][1]) i++;
256	    else j++;
257	  }
258	  return out;
259	}
