261	// 多资源在窗口 [wStart, wEnd) 内的共同实际可用区间：
262	// 各自实际可用时间（开放合并后扣除有效停用并集）裁进窗口后逐组求交
263	function commonAvailableSegments(
264	  store: Store,
265	  ids: string[],
266	  wStart: number,
267	  wEnd: number,
268	): Array<[number, number]> {
269	  let common: Array<[number, number]> = [[wStart, wEnd]];
270	  for (const id of ids) {
271	    const r = store.resources.find((x) => x.id === id)!;
272	    const clipped = clipSegments(availableSegmentsOf(store, r), wStart, wEnd);
273	    common = intersectSegments(common, clipped);
274	    if (common.length === 0) break;
275	  }
276	  return common;
277	}
