1607	
1608	interface ValidationTarget {
1609	  startMin: number;
1610	  endMin: number;
1611	  resourceIds: string[]; // 已校验、按标识排序的完整目标资源集合
1612	}
1613	
1614	interface BatchTargetFailure {
1615	  index: number; // 目标数组下标（0 基）；报告顺序与业务定位由入口决定
1616	  gaps: CoverageGap[]; // 实际可用时间不能完整覆盖目标的资源及相关有效停用
1617	  external: Conflict[]; // 与批外有效预约的冲突（按预约标识排序）
1618	  internal: Array<{otherIndex: number; shared: string[]}>; // 批内冲突（双方互见）
1619	}
1620	
1621	// excludeBookingIds：本批涉及预约的标识，其当前占用不计入批外占用
1622	// （改期与撤销据此允许整批交换时段和资源；系列与导入传空集合）
1623	function validateBatchTargets(
1624	  store: Store,
1625	  targets: ReadonlyArray<ValidationTarget>,
1626	  excludeBookingIds: ReadonlySet<string> = new Set<string>(),
1627	): BatchTargetFailure[] {
1628	  const failures: BatchTargetFailure[] = [];
1629	  for (let i = 0; i < targets.length; i++) {
1630	    const t = targets[i];
1631	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
1632	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
1633	      (c) => !excludeBookingIds.has(c.booking.id),
1634	    );
1635	    const wanted = new Set(t.resourceIds);
1636	    const internal: BatchTargetFailure['internal'] = [];
1637	    for (let j = 0; j < targets.length; j++) {
1638	      if (j === i) continue;
1639	      const o = targets[j];
1640	      if (!(o.startMin < t.endMin && t.startMin < o.endMin)) continue;
1641	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
1642	      if (shared.length > 0) internal.push({otherIndex: j, shared});
1643	    }
1644	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1645	      failures.push({index: i, gaps, external, internal});
1646	    }
1647	  }
1648	  return failures;
1649	}
