1686	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
1687	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1688	  const allowedSet = new Set(allowed);
1689	  const multiSet = new Set(multi);
1690	  const values = new Map<string, string[]>();
1691	  const positionals: string[] = [];
1692	
1693	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1694	    if (inline !== undefined) return [inline, index];
1695	    const v = args[index + 1];
1696	    if (v === undefined || v.startsWith('-')) {
1697	      throw new UsageError(`选项 --${key} 缺少值`);
1698	    }
1699	    return [v, index + 1];
1700	  };
1701	
1702	  for (let i = 0; i < args.length; i++) {
1703	    const a = args[i];
1704	    if (a.startsWith('--')) {
1705	      let key: string;
1706	      let inline: string | undefined;
1707	      const eq = a.indexOf('=');
1708	      if (eq >= 0) {
1709	        key = a.slice(2, eq);
1710	        inline = a.slice(eq + 1);
1711	      } else {
1712	        key = a.slice(2);
1713	      }
1714	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1715	      let v: string;
1716	      [v, i] = takeValue(key, inline, i);
1717	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1718	      if (!multiSet.has(key) && values.has(key)) {
1719	        throw new UsageError(`选项 --${key} 只能指定一次`);
1720	      }
1721	      const list = values.get(key) ?? [];
1722	      list.push(v);
1723	      values.set(key, list);
1724	    } else if (a.startsWith('-') && a !== '-') {
1725	      throw new UsageError(`未知参数: ${a}`);
1726	    } else {
1727	      positionals.push(a);
1728	    }
1729	  }
1730	  return {values, positionals};
1731	}
1732	
1733	function requireFlag(values: Map<string, string[]>, key: string): string {
1734	  const v = values.get(key)?.[0];
1735	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
1736	  return v;
1737	}
