3110	function lexMinAssignment(
3111	  groups: RequirementGroup[],
3112	  usable: (id: string) => boolean,
3113	): string[] | null {
3114	  const chosen: string[] = [];
3115	  const used = new Set<string>();
3116	
3117	  // 第 from 组起（0 基）在 used 之外能否各选一个互不相同的可用候选
3118	  const restMatchable = (from: number): boolean => {
3119	    const match = new Map<string, number>(); // 资源 -> 组下标
3120	    const tryAssign = (g: number, seen: Set<string>): boolean => {
3121	      for (const id of groups[g].candidates) {
3122	        if (used.has(id) || seen.has(id) || !usable(id)) continue;
3123	        seen.add(id);
3124	        const owner = match.get(id);
3125	        if (owner === undefined || tryAssign(owner, seen)) {
3126	          match.set(id, g);
3127	          return true;
3128	        }
3129	      }
3130	      return false;
3131	    };
3132	    for (let g = from; g < groups.length; g++) {
3133	      if (!tryAssign(g, new Set())) return false;
3134	    }
3135	    return true;
3136	  };
3137	
3138	  for (let g = 0; g < groups.length; g++) {
3139	    let picked: string | null = null;
3140	    for (const id of groups[g].candidates) {
3141	      if (used.has(id) || !usable(id)) continue;
3142	      used.add(id);
3143	      if (restMatchable(g + 1)) {
3144	        picked = id;
3145	        break;
3146	      }
3147	      used.delete(id);
3148	    }
3149	    if (picked === null) return null;
3150	    chosen.push(picked);
3151	  }
3152	  return chosen;
3153	}
