3158	function findEarliestSlot(
3159	  store: Store,
3160	  groups: RequirementGroup[],
3161	  wStart: number,
3162	  wEnd: number,
3163	  duration: number,
3164	): {startMin: number; endMin: number; picks: string[]} | null {
3165	  const freeById = new Map<string, Array<[number, number]>>();
3166	  const starts = new Set<number>();
3167	  for (const g of groups) {
3168	    for (const id of g.candidates) {
3169	      if (freeById.has(id)) continue;
3170	      const free = resourceFreeSegments(store, id, wStart, wEnd);
3171	      freeById.set(id, free);
3172	      for (const [s, e] of free) {
3173	        if (e - s >= duration) starts.add(s);
3174	      }
3175	    }
3176	  }
3177	
3178	  const usableAt = (s: number): ((id: string) => boolean) => {
3179	    const e = s + duration;
3180	    const cache = new Map<string, boolean>();
3181	    return (id: string): boolean => {
3182	      let v = cache.get(id);
3183	      if (v === undefined) {
3184	        v = isFullyCovered(freeById.get(id)!, s, e);
3185	        cache.set(id, v);
3186	      }
3187	      return v;
3188	    };
3189	  };
3190	
3191	  for (const s of [...starts].sort((a, b) => a - b)) {
3192	    if (s + duration > wEnd) continue; // 结束不得超出窗口
3193	    const picks = lexMinAssignment(groups, usableAt(s));
3194	    if (picks !== null) return {startMin: s, endMin: s + duration, picks};
3195	  }
3196	  return null;
3197	}
