3920	function parseFlexRescheduleItems(
3921	  store: Store,
3922	  records: Array<Record<string, unknown>>,
3923	  file: string,
3924	): FlexRescheduleItem[] {
3925	  const problems: string[] = [];
3926	  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
3927	  const items: Array<FlexRescheduleItem | null> = records.map((rec, idx) => {
3928	    const bookingId = rec.bookingId as string;
3929	    const at = `第 ${idx + 1} 项（${bookingId}）`;
3930	    let ok = true;
3931	
3932	    const firstAt = seenBooking.get(bookingId);
3933	    if (firstAt !== undefined) {
3934	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
3935	      ok = false;
3936	    } else {
3937	      seenBooking.set(bookingId, idx + 1);
3938	    }
3939	
3940	    const booking = store.bookings.find((b) => b.id === bookingId);
3941	    if (!booking) {
3942	      problems.push(`${at} 未知预约标识: ${bookingId}`);
3943	      ok = false;
3944	    } else if (booking.status === 'cancelled') {
3945	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
3946	      ok = false;
3947	    }
3948	
3949	    let win: {start: string; end: string; startMin: number; endMin: number} | null = null;
3950	    try {
3951	      win = parseFlexWindow(rec.window as string, `${at}窗口`);
3952	    } catch (err) {
3953	      if (err instanceof BizError) {
3954	        problems.push(err.message);
3955	        ok = false;
3956	      } else {
3957	        throw err;
3958	      }
3959	    }
3960	
3961	    let duration = 0;
3962	    let curStartMin = 0;
3963	    if (booking !== undefined) {
3964	      curStartMin = parseDateTime(booking.start, `${at} 当前开始时间`);
3965	      duration = parseDateTime(booking.end, `${at} 当前结束时间`) - curStartMin;
3966	    }
3967	    if (win !== null && booking !== undefined && win.endMin - win.startMin < duration) {
3968	      problems.push(
3969	        `${at} 窗口长度 ${win.endMin - win.startMin} 分钟小于预约当前时长 ${duration} 分钟` +
3970	          `（窗口: ${win.start} → ${win.end}，时长保持预约当前长度）`,
3971	      );
3972	      ok = false;
3973	    }
3974	
3975	    const groups: RequirementGroup[] = [];
3976	    (rec.groups as string[][]).forEach((ids, gi) => {
3977	      const glabel = `${at} 第 ${gi + 1} 候选资源组`;
3978	      const seen = new Set<string>();
3979	      const dupes: string[] = [];
3980	      for (const id of ids) {
3981	        if (seen.has(id) && !dupes.includes(id)) dupes.push(id);
3982	        seen.add(id);
3983	      }
3984	      if (dupes.length > 0) {
3985	        problems.push(`${glabel}内候选资源重复: ${dupes.join('、')}`);
3986	        ok = false;
3987	      }
3988	      const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
3989	      if (unknown.length > 0) {
3990	        problems.push(`${glabel}含未知资源标识: ${unknown.join('、')}`);
3991	        ok = false;
3992	      }
3993	      groups.push({index: gi + 1, candidates: [...seen].sort()});
3994	    });
3995	
3996	    if (!ok || win === null || booking === undefined) return null;
3997	    return {
3998	      index: idx + 1,
3999	      booking,
4000	      startRaw: win.start,
4001	      endRaw: win.end,
4002	      startMin: win.startMin,
4003	      endMin: win.endMin,
4004	      duration,
4005	      curStartMin,
4006	      curResourceIds: [...booking.resourceIds].sort(),
4007	      groups,
4008	    };
4009	  });
4010	  if (problems.length > 0) {
4011	    throw new BizError(`改期清单 ${file} 校验失败，整单拒绝（原有安排保持不变）：\n${problems.map((p) => `- ${p}`).join('\n')}`);
4012	  }
4013	  return items as FlexRescheduleItem[];
