4016	// 所选资源序列（按组顺序）与当前资源集合是否一致（资源顺序不计）
4017	function sameResourceSet(picks: string[], curSorted: string[]): boolean {
4018	  if (picks.length !== curSorted.length) return false;
4019	  const sorted = [...picks].sort();
4020	  return sorted.every((id, i) => id === curSorted[i]);
