4023	// 联合求解整单最终安排：先最小化变化预约数量，数量相同再按清单顺序逐项
4024	// 先比开始分钟、再按组序比资源标识字符串，取字典序最小完整方案。
4025	// 返回按清单顺序的各项安排（开始分钟 + 各组所选资源），无整体解返回 null。
4026	// extraCutsById 给出拟登记但尚未落盘的停用区间（add-closure 附改期清单时
4027	// 与既有有效停用一并扣除），省略时只扣除已落盘的有效停用。
4028	function solveFlexReschedule(
4029	  store: Store,
4030	  items: FlexRescheduleItem[],
4031	  extraCutsById?: ReadonlyMap<string, ReadonlyArray<[number, number]>>,
4032	): FlexPlacement[] | null {
4033	  // 本批预约的旧占用一律不视为障碍；其余有效预约按现状阻挡
4034	  const batchIds = new Set(items.map((it) => it.booking.id));
4035	  const baseFree: Array<Map<string, Array<[number, number]>>> = items.map((it) => {
4036	    const m = new Map<string, Array<[number, number]>>();
4037	    for (const g of it.groups) {
4038	      for (const id of g.candidates) {
4039	        if (!m.has(id)) {
4040	          m.set(id, resourceFreeSegments(store, id, it.startMin, it.endMin, batchIds, extraCutsById?.get(id) ?? []));
4041	        }
4042	      }
4043	    }
4044	    return m;
4045	  });
4046	
4047	  // 候选开始分钟闭包：基础空闲段起点 ∪ 各项当前开始（在窗内时），
4048	  // 加上“被其他项占用结束顶住”的起点 s_i = s_j + d_j
4049	  // （仅候选资源集合有交集的项之间传播；值域有限，必收敛）
4050	  const candidateIds = items.map((it) => {
4051	    const set = new Set<string>();
4052	    for (const g of it.groups) for (const id of g.candidates) set.add(id);
4053	    return set;
4054	  });
4055	  const sharesCandidate = (a: number, b: number): boolean => {
4056	    for (const id of candidateIds[a]) if (candidateIds[b].has(id)) return true;
4057	    return false;
4058	  };
4059	  const candStarts: Array<Set<number>> = items.map((it, i) => {
4060	    const set = new Set<number>();
4061	    for (const segs of baseFree[i].values()) {
4062	      for (const [s] of segs) {
4063	        if (s + it.duration <= it.endMin) set.add(s);
4064	      }
4065	    }
4066	    // 当前开始落在窗内时，“保持现状”总是一个候选（是否可行在试探中判定）
4067	    if (it.curStartMin >= it.startMin && it.curStartMin + it.duration <= it.endMin) {
4068	      set.add(it.curStartMin);
4069	    }
4070	    return set;
4071	  });
4072	  let changed = true;
4073	  while (changed) {
4074	    changed = false;
4075	    for (let j = 0; j < items.length; j++) {
4076	      for (let i = 0; i < items.length; i++) {
4077	        if (i === j || !sharesCandidate(i, j)) continue;
4078	        for (const s of candStarts[j]) {
4079	          const t = s + items[j].duration;
4080	          if (
4081	            t >= items[i].startMin &&
4082	            t + items[i].duration <= items[i].endMin &&
4083	            !candStarts[i].has(t)
4084	          ) {
4085	            candStarts[i].add(t);
4086	            changed = true;
4087	          }
4088	        }
4089	      }
4090	    }
4091	  }
4092	
4093	  // 已放置项对各资源的占用（随试探入栈/出栈增减；不变项同样放置以阻挡他项）
4094	  const occById = new Map<string, Array<[number, number]>>();
4095	
4096	  // 按清单顺序深度优先：开始分钟升序、同一开始的资源序列字典序升序，
4097	  // 只接受变化数不超过 budget 的完整方案；首个完整方案即该预算下的最小方案
4098	  const search = (idx: number, budget: number): FlexPlacement[] | null => {
4099	    if (idx === items.length) return [];
4100	    const it = items[idx];
4101	    const freeById = new Map<string, Array<[number, number]>>();
4102	    for (const [id, segs] of baseFree[idx]) {
4103	      const occ = occById.get(id);
4104	      freeById.set(id, occ !== undefined && occ.length > 0 ? subtractSegments(segs, occ) : segs);
4105	    }
4106	    for (const s of [...candStarts[idx]].sort((a, b) => a - b)) {
4107	      const e = s + it.duration;
4108	      const cache = new Map<string, boolean>();
4109	      const usable = (id: string): boolean => {
4110	        let v = cache.get(id);
4111	        if (v === undefined) {
4112	          v = isFullyCovered(freeById.get(id)!, s, e);
4113	          cache.set(id, v);
4114	        }
4115	        return v;
4116	      };
4117	      for (const picks of assignmentsInLexOrder(it.groups, usable)) {
4118	        // 起止时间或完整资源集合任一不同才算变化（时长固定，开始即决定结束；资源顺序不计）
4119	        const cost = s === it.curStartMin && sameResourceSet(picks, it.curResourceIds) ? 0 : 1;
4120	        if (cost > budget) continue;
4121	        for (const id of picks) {
4122	          const occ = occById.get(id) ?? [];
4123	          occ.push([s, e]);
4124	          occById.set(id, occ);
4125	        }
4126	        const rest = search(idx + 1, budget - cost);
4127	        if (rest !== null) return [{startMin: s, endMin: e, picks}, ...rest];
4128	        for (const id of picks) occById.get(id)!.pop();
4129	      }
4130	    }
4131	    return null;
4132	  };
4133	
4134	  // 变化数 k 递增：首个有解的 k 即最少变化数，其首个完整方案即最终取舍
4135	  for (let k = 0; k <= items.length; k++) {
4136	    const plan = search(0, k);
4137	    if (plan !== null) return plan;
4138	  }
4139	  return null;
4140	}
