4240	// 资源使用率与繁忙时段统计（usage-stats，只读）
4241	//
4242	// 统计窗口内所选资源的实际可用、占用、空闲分钟与使用率（逐日 + 整窗），
4243	// 并给出同时被占用的所选资源数量峰值及全部达到峰值的最大连续区间。
4244	// 实际可用时间 = 开放区间合并重叠或相接后扣除有效停用并集，再裁剪到窗口；
4245	// 占用只计有效预约（普通、系列成员、导入、候补兑现同口径；已取消预约/停用、
4246	// 未兑现候补、导入首次请求快照与改期历史快照均不计）的当前时间与当前资源，
4247	// 并取与实际可用区间的交集，同一资源的重叠占用合并、一分钟只计一次。
4248	// 本命令只读一份完整快照：不取写入保护、不写数据文件、不推进任何计数。
4249	// ---------------------------------------------------------------------------
4250	
4251	// 一组互不相交区间的总分钟数
4252	function totalMinutes(segments: Array<[number, number]>): number {
4253	  return segments.reduce((sum, [s, e]) => sum + (e - s), 0);
4254	}
4255	
4256	// 使用率百分比：占用/可用，四舍五入至两位小数；分母为零显示“不适用”
4257	function formatUsagePercent(occupied: number, available: number): string {
4258	  if (available === 0) return '不适用';
4259	  return `${(Math.round((occupied * 10000) / available) / 100).toFixed(2)}%`;
4260	}
4261	
4262	// 营业地日历日序号 -> YYYY-MM-DD（与机器时区无关；调用方保证年份在 0001-9999 内）
4263	function formatBusinessDate(dayIndex: number): string {
4264	  const {y, m, d} = civilFromDays(dayIndex);
4265	  return `${String(y).padStart(4, '0')}-${pad2(m)}-${pad2(d)}`;
4266	}
