function parseLockInfo(text: string): LockInfo | null {
  try {
    const parsed = JSON.parse(text) as LockInfo;
    if (!Number.isInteger(parsed.pid) || parsed.pid <= 0 || typeof parsed.host !== 'string') {
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

