80	async function waitForSyncPoint(path: string, ctx: string, timeoutMs = 15000): Promise<void> {
81	  const deadline = Date.now() + timeoutMs;
82	  while (!existsSync(path)) {
83	    if (Date.now() > deadline) throw new Error(`等待同步点超时: ${ctx}（${path}）`);
84	    await new Promise((r) => setTimeout(r, 10));
85	  }
