function parseBufferMinutes(raw: string, label: string): number {
  if (!/^(0|[1-9]\d*)$/.test(raw)) {
    throw new BizError(`${label}非法: “${raw}”，必须是非负整数分钟`);
  }
  const n = Number(raw);
  if (!Number.isSafeInteger(n)) {
    throw new BizError(`${label}过大: “${raw}”，必须是不超过 ${Number.MAX_SAFE_INTEGER} 的非负安全整数`);
  }
  return n;
}

