  // find-slot：窗口 09:00-10:00、时长 60 -> 最早活动 09:30（占用 09:00-10:30）
  const slot = ok(
    df,
    ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T10:00', '--duration', '60', '--group', 'R0001'],
