  // 窗口只到 09:30、时长 30：最早活动需 09:30，活动结束恰为窗尾 -> 无解（退出 0）
  const none = ok(
    df,
    ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T09:30', '--duration', '30', '--group', 'R0001'],
    '窗口装不下含准备活动',
  );
