    '准备在开放前',
  );
  assert.match(cover.stderr, /实际占用: 2026-10-12T08:30 → 2026-10-12T10:00/);

  // 弹性候补登记同样要求扣除前后预留后能容纳；窗口 09:00-09:30 时长 30 拒绝
  const reg = bizFail(
    df,
    ['add-flex-waitlist', '--resource', 'R0001', '--window', '2026-10-12T09:00/2026-10-12T09:30', '--duration', '30'],
