    df,
    ['add-flex-waitlist', '--resource', 'R0001', '--window', '2026-10-12T09:00/2026-10-12T10:00', '--duration', '60'],
    '弹性候补可登记',
  );
  const proc = ok(df, ['process-waitlist'], '兑现弹性候补');
  assert.match(proc.stdout, /实际时间: 2026-10-12T09:30 → 2026-10-12T10:30/);
});

